contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0, "empty tos");
        require(address(this).balance >= msg.value, "not enough balance");

        uint balBefore = address(c).balance;

        bool reverted;
        bool returned;
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            reverted = false;
            returned = r;
        } catch {
            reverted = true;
            returned = false;
        }

        if (!reverted) {
            assert(returned == true);
            assert(address(c).balance <= balBefore + msg.value);
            for (uint i = 0; i < _tos.length; i++) {
                (bool s, ) = caddress.call(abi.encodeWithSelector(bytes4(keccak256("transferFrom(address,address,uint256)")), from, _tos[i], v));
                assert(s);
            }
        } else {
            assert(address(c).balance == balBefore);
        }
    }

    receive() external payable {}
}

